function kthGrammar(n, k) {
  if (n === 1) return 0;                           // row 1 is just "0"
  const parent = kthGrammar(n - 1, Math.ceil(k / 2));
  return k % 2 === 1 ? parent : 1 - parent;        // left child copies, right child flips
}

def kth_grammar(n, k):
    if n == 1:
